def nCr_mod_p(n, r, p): 
	if (r > n- r): 
		r = n - r 
	C = [0 for i in range(r + 1)] 
	C[0] = 1 
	for i in range(1, n + 1): 
		for j in range(min(i, r), 0, -1): 
			C[j] = (C[j] + C[j-1]) % p 
	return C[r]

def find_next_number(n: int, z: int) -> int:
    def subsets(collection):
        if len(collection) == 1:
            yield [collection]
            return

        first = collection[0]
        for smaller in subsets(collection[1:]):
            yield [first] + smaller
            for i, subset in enumerate(smaller):
                yield smaller[:i] + [first + subset] + smaller[i+1:]

    def bucket_digit_distributions_total_sum(n: int) -> int:
        # Calculate the sum of all possible bucket distributions
        return sum(sum(map(int, sub)) for sub in subsets(str(n))) - n

    f_nf = bucket_digit_distributions_total_sum(n) + z
    while True:
        n += 1
        if bucket_digit_distributions_total_sum(n) > f_nf:
            return n

from typing import List

def max_adjacent_product(array: List[int]) -> int:
    # Calculate the maximum product of adjacent elements
    return max(a * b for a, b in zip(array, array[1:]))

def sum_adjacent_until_single(arr: list[int]) -> int:
    while len(arr) > 1:
        arr = [x + y for x, y in zip(arr, arr[1:])]
    return arr[0]

def find_first_non_consecutive(arr: list[int]) -> int | None:
    if not arr:
        return None  # Return None for empty array
    for i, x in enumerate(arr[:-1]):
        if x + 1 != arr[i + 1]:
            return arr[i + 1]  # Return the first non-consecutive number
    return None  # Return None if all elements are consecutive

